if (spawnPowerup)
temp = Instantiate(powerupPrefab) as GameObject;
else
temp = Instantiate(obstaclePrefab) as GameObject;
Vector3 position = temp.transform.position;
position.x = Random.Range(-3f, 3f);
temp.transform.position = position;
